INSERT INTO `pnn_content` VALUES (1,0,'Beranda','beranda','<p>Selamat datang di website Pengadilan Negeri Natuna Kelas II. Halaman ini sedang disusun ulang berdasarkan Juknis Pembaruan Website 2026.</p>','',1,9,'2026-06-17 15:26:53',285,'','2026-06-17 15:26:53',285,NULL,NULL,'2000-01-01 00:00:00',NULL,'{}','{}','{}',1,1,'','',1,1644,'{}',1,'*','pn-natuna-bootstrap'),(2,0,'Profil Pengadilan','profil-pengadilan','<p>Profil Pengadilan Negeri Natuna Kelas II memuat informasi dasar satuan kerja, visi dan misi, serta informasi kelembagaan yang dibutuhkan masyarakat.</p><ul class=\"service-links\"><li><a href=\"index.php?option=com_content&view=article&id=10\">Visi dan Misi</a></li><li><a href=\"index.php/kontak\">Kontak dan Alamat</a></li></ul>','',1,8,'2026-06-17 15:26:53',285,'','2026-06-18 10:17:16',285,NULL,NULL,'2000-01-01 00:00:00',NULL,'{}','{}','{}',1,2,'','',1,0,'{}',0,'*','pn-natuna-bootstrap'),(3,0,'Layanan Publik','layanan-publik','<p>Layanan Publik Pengadilan Negeri Natuna Kelas II disusun untuk memudahkan masyarakat memperoleh informasi layanan PTSP, standar pelayanan, maklumat, kompensasi layanan, layanan disabilitas, dan permohonan informasi.</p><ul class=\"service-links\"><li><a href=\"index.php?option=com_content&view=article&id=11\">Jenis Layanan PTSP</a></li><li><a href=\"index.php?option=com_content&view=article&id=12\">Standar Pelayanan</a></li><li><a href=\"index.php?option=com_content&view=article&id=13\">Maklumat Pelayanan</a></li><li><a href=\"index.php?option=com_content&view=article&id=14\">Kompensasi Layanan</a></li><li><a href=\"index.php?option=com_content&view=article&id=15\">Layanan Disabilitas</a></li><li><a href=\"index.php?option=com_content&view=article&id=19\">Prosedur Permohonan Informasi</a></li></ul>','',1,9,'2026-06-17 15:26:53',285,'','2026-06-18 10:17:16',285,NULL,NULL,'2000-01-01 00:00:00',NULL,'{}','{}','{}',1,3,'','',1,0,'{}',0,'*','pn-natuna-bootstrap'),(4,0,'Layanan Hukum','layanan-hukum','<p>Layanan Hukum Pengadilan Negeri Natuna meliputi informasi Pos Bantuan Hukum, pembebasan biaya perkara, dan layanan hukum lain sesuai ketentuan peraturan perundang-undangan.</p><ul class=\"service-links\"><li><a href=\"index.php?option=com_content&view=article&id=16\">Pos Bantuan Hukum</a></li><li><a href=\"index.php?option=com_content&view=article&id=17\">Pembebasan Biaya Perkara (Prodeo)</a></li></ul>','',1,10,'2026-06-17 15:26:53',285,'','2026-06-18 10:17:16',285,NULL,NULL,'2000-01-01 00:00:00',NULL,'{}','{}','{}',1,4,'','',1,0,'{}',0,'*','pn-natuna-bootstrap'),(5,0,'Informasi Perkara','informasi-perkara','<p>Informasi Perkara Pengadilan Negeri Natuna mengarahkan masyarakat ke sistem resmi untuk menelusuri perkara, jadwal sidang, direktori putusan, dan informasi biaya perkara.</p><ul class=\"service-links\"><li><a href=\"https://sipp.pn-natuna.go.id/\" target=\"_blank\" rel=\"noopener\">SIPP PN Natuna</a></li><li><a href=\"https://sipp.pn-natuna.go.id/list_jadwal_sidang/\" target=\"_blank\" rel=\"noopener\">Jadwal Sidang</a></li><li><a href=\"https://putusan3.mahkamahagung.go.id/\" target=\"_blank\" rel=\"noopener\">Direktori Putusan</a></li><li><a href=\"index.php?option=com_content&view=article&id=18\">Biaya Perkara</a></li></ul>','',1,11,'2026-06-17 15:26:53',285,'','2026-06-18 10:17:16',285,NULL,NULL,'2000-01-01 00:00:00',NULL,'{}','{}','{}',1,5,'','',1,0,'{}',0,'*','pn-natuna-bootstrap'),(6,0,'Berita dan Pengumuman','berita-dan-pengumuman','<p>Halaman ini menjadi indeks berita dan pengumuman resmi Pengadilan Negeri Natuna Kelas II. Susunan ini mengikuti blok Juknis: berita terkini, pengumuman, dan tautan informasi resmi yang mudah dipindai masyarakat.</p><div class=\"info-tabs\"><a class=\"info-tab\" href=\"/berita\"><strong>Berita Terkini</strong><span>Kegiatan pengadilan, pelayanan publik, pembinaan aparatur, dan publikasi kelembagaan.</span></a><a class=\"info-tab\" href=\"/pengumuman\"><strong>Pengumuman Resmi</strong><span>Informasi seleksi, layanan Posbakum, pemberitahuan layanan, dan pengumuman satuan kerja.</span></a></div><h2>Berita Terbaru</h2><ul class=\"service-links\"><li><a href=\"/pengambilan-sumpah-atau-janji-cpns-menjadi-pns\">Pengambilan Sumpah atau Janji CPNS Menjadi PNS</a></li><li><a href=\"/upacara-hari-lahir-pancasila-2026\">Upacara Hari Lahir Pancasila</a></li><li><a href=\"/pelaksanaan-upacara-hari-kebangkitan-nasional-ke-118-tahun-2026\">Upacara Hari Kebangkitan Nasional Ke-118</a></li><li><a href=\"/sosialisasi-pelayanan-prima-2026\">Sosialisasi Pelayanan Prima</a></li></ul><h2>Pengumuman</h2><ul><li><a href=\"/pengumuman-penetapan-dan-pemenang-posbakum-ta-2026\">Pengumuman Penetapan dan Pemenang Posbakum TA 2026</a></li><li><a href=\"/pengumuman-seleksi-posbakum-tahun-2026\">Pengumuman Seleksi Posbakum Tahun 2026</a></li></ul><p class=\"content-note\">Informasi yang bersifat layanan perkara tetap diarahkan ke kanal resmi seperti SIPP, e-Court, Direktori Putusan, dan tautan layanan Mahkamah Agung/Badilum.</p>','',1,12,'2026-06-17 15:26:53',285,'','2026-06-19 14:14:34',0,NULL,NULL,'2000-01-01 00:00:00',NULL,'{}','{}','{}',1,6,'','',1,0,'{}',0,'*','pn-natuna-bootstrap'),(7,0,'Zona Integritas','zona-integritas','<p>Halaman ini sedang disusun ulang berdasarkan Juknis Pembaruan Website 2026. Konten final akan dimigrasikan dari website lama setelah proses validasi.</p>','',1,14,'2026-06-17 15:26:53',285,'','2026-06-17 15:26:53',285,NULL,NULL,'2000-01-01 00:00:00',NULL,'{}','{}','{}',1,7,'','',1,6,'{}',0,'*','pn-natuna-bootstrap'),(8,0,'Transparansi','transparansi','<p>Halaman ini sedang disusun ulang berdasarkan Juknis Pembaruan Website 2026. Konten final akan dimigrasikan dari website lama setelah proses validasi.</p>','',1,15,'2026-06-17 15:26:53',285,'','2026-06-17 15:26:53',285,NULL,NULL,'2000-01-01 00:00:00',NULL,'{}','{}','{}',1,8,'','',1,1,'{}',0,'*','pn-natuna-bootstrap'),(9,0,'Kontak','kontak','<div class=\"kontak-page\">\n  <section class=\"kontak-hero-card\">\n    <div>\n      <h2>Pengadilan Negeri Natuna Kelas II</h2>\n      <p>Silakan gunakan kanal resmi berikut untuk menghubungi Pengadilan Negeri Natuna Kelas II, memperoleh informasi layanan, melihat lokasi kantor, atau mengikuti media sosial resmi pengadilan.</p>\n    </div>\n    <div class=\"kontak-status-card\">\n      <img src=\"/images/icons/contact-clock.svg\" alt=\"\" aria-hidden=\"true\" loading=\"lazy\" decoding=\"async\">\n      <strong>Jam layanan</strong>\n      <span>Senin-Kamis 08.00-16.30 WIB</span>\n      <span>Jumat 08.00-17.00 WIB</span>\n    </div>\n  </section>\n\n  <section class=\"kontak-grid\" aria-label=\"Informasi kontak resmi\">\n    <article class=\"kontak-info-card kontak-address-card\">\n      <span class=\"kontak-icon\" aria-hidden=\"true\"><img src=\"/images/icons/contact-map.svg\" alt=\"\" loading=\"lazy\" decoding=\"async\"></span>\n      <div>\n        <p class=\"kontak-label\">Alamat kantor</p>\n        <h3>Jalan Batu Sisir, Desa Sungai Ulu</h3>\n        <p>Kecamatan Bunguran Timur, Kabupaten Natuna, Provinsi Kepulauan Riau.</p>\n      </div>\n    </article>\n\n    <article class=\"kontak-info-card\">\n      <span class=\"kontak-icon\" aria-hidden=\"true\"><img src=\"/images/icons/contact-phone.svg\" alt=\"\" loading=\"lazy\" decoding=\"async\"></span>\n      <div>\n        <p class=\"kontak-label\">Telepon</p>\n        <h3><a href=\"tel:07733211203\">0773-3211203</a></h3>\n        <p>Gunakan nomor kantor pada jam layanan untuk informasi umum dan layanan pengadilan.</p>\n      </div>\n    </article>\n\n    <article class=\"kontak-info-card\">\n      <span class=\"kontak-icon\" aria-hidden=\"true\"><img src=\"/images/icons/contact-email.svg\" alt=\"\" loading=\"lazy\" decoding=\"async\"></span>\n      <div>\n        <p class=\"kontak-label\">Email resmi</p>\n        <h3><a href=\"mailto:pn.natuna@gmail.com\">pn.natuna@gmail.com</a></h3>\n        <p>Kirim pertanyaan resmi, permohonan informasi, atau korespondensi administratif melalui email.</p>\n      </div>\n    </article>\n  </section>\n\n  <section class=\"kontak-social-panel\" aria-label=\"Kanal sosial media resmi\">\n    <div>\n      <p class=\"kontak-label\">Kanal resmi</p>\n      <h3>Ikuti PN Natuna di media sosial</h3>\n      <p>Dapatkan informasi kegiatan, pengumuman, dan publikasi layanan melalui kanal resmi berikut.</p>\n    </div>\n    <div class=\"kontak-social-grid\">\n      <a class=\"kontak-social-link kontak-social-wa\" href=\"https://wa.me/6281261256661\" target=\"_blank\" rel=\"noopener\"><img src=\"/images/social/whatsapp.svg\" alt=\"\"><span>WhatsApp</span><small>Chat layanan</small></a>\n      <a class=\"kontak-social-link\" href=\"https://www.instagram.com/pn.natuna/\" target=\"_blank\" rel=\"noopener\"><img src=\"/images/social/instagram.svg\" alt=\"\"><span>Instagram</span><small>@pn.natuna</small></a>\n      <a class=\"kontak-social-link\" href=\"https://www.facebook.com/pn.natuna\" target=\"_blank\" rel=\"noopener\"><img src=\"/images/social/facebook.svg\" alt=\"\"><span>Facebook</span><small>PN Natuna</small></a>\n      <a class=\"kontak-social-link\" href=\"https://www.youtube.com/@pengadilannegeriranai9849\" target=\"_blank\" rel=\"noopener\"><img src=\"/images/social/youtube.svg\" alt=\"\"><span>YouTube</span><small>Video kegiatan</small></a>\n    </div>\n  </section>\n\n  <section class=\"kontak-action-map\">\n    <div class=\"kontak-action-panel\">\n      <p class=\"kontak-label\">Akses lokasi</p>\n      <h3>Datang ke kantor PN Natuna</h3>\n      <p>Gunakan peta berikut untuk melihat posisi kantor dan membuka rute perjalanan melalui Google Maps.</p>\n      <div class=\"kontak-actions\">\n        <a class=\"kontak-primary-link\" href=\"https://www.google.com/maps/search/?api=1&query=Pengadilan+Negeri+Natuna\" target=\"_blank\" rel=\"noopener\">Buka Google Maps</a>\n        <a class=\"kontak-secondary-link\" href=\"mailto:pn.natuna@gmail.com\">Kirim email</a>\n      </div>\n    </div>\n    <div class=\"kontak-map-card\">\n      <iframe title=\"Peta lokasi Pengadilan Negeri Natuna\" src=\"https://www.google.com/maps?q=Pengadilan%20Negeri%20Natuna&output=embed\" loading=\"lazy\" referrerpolicy=\"no-referrer-when-downgrade\"></iframe>\n    </div>\n  </section>\n</div>','',1,9,'2026-06-17 15:26:53',285,'','2026-06-18 11:09:20',285,NULL,NULL,'2000-01-01 00:00:00',NULL,'{}','{}','{}',1,9,'','',1,0,'{}',0,'*','pn-natuna-bootstrap'),(10,0,'Visi dan Misi Pengadilan Negeri Natuna','visi-dan-misi-pengadilan-negeri-natuna','<div class=\"visimisi-page\">\n  <section class=\"visimisi-hero-card\">\n    <div class=\"visimisi-hero-copy\">\n      <p class=\"visimisi-kicker\">Arah layanan peradilan</p>\n      <h2>Visi dan Misi Pengadilan Negeri Natuna Kelas II</h2>\n      <p class=\"visimisi-lead\">Visi dan misi menjadi arah kerja Pengadilan Negeri Natuna Kelas II dalam menjaga kemandirian peradilan, meningkatkan kualitas pelayanan hukum, serta membangun kepercayaan masyarakat melalui pelayanan yang transparan dan berkeadilan.</p>\n    </div>\n    <figure class=\"visimisi-illustration\">\n      <img src=\"/images/ilustrasi/visi-misi-pn-natuna.svg\" alt=\"Ilustrasi visi misi Pengadilan Negeri Natuna\" width=\"960\" height=\"720\" loading=\"eager\" decoding=\"async\">\n      <figcaption>Ilustrasi arah pelayanan: independensi, keadilan, transparansi, dan pelayanan publik.</figcaption>\n    </figure>\n  </section>\n\n  <section class=\"visimisi-vision-card\" aria-label=\"Visi Pengadilan Negeri Natuna\">\n    <span>Visi</span>\n    <blockquote>Terwujudnya Pengadilan Negeri Natuna Kelas II yang Agung.</blockquote>\n    <p>Visi ini menegaskan komitmen pengadilan untuk menghadirkan lembaga peradilan yang mandiri, berintegritas, profesional, dan dipercaya masyarakat.</p>\n  </section>\n\n  <section class=\"visimisi-mission-section\" aria-label=\"Misi Pengadilan Negeri Natuna\">\n    <div class=\"visimisi-section-heading\">\n      <p>Misi</p>\n      <h3>Empat arah kerja utama</h3>\n    </div>\n    <div class=\"visimisi-mission-grid\">\n      <article>\n        <span>01</span>\n        <h4>Menjaga kemandirian pengadilan</h4>\n        <p>Menegakkan prinsip independensi peradilan agar setiap perkara diperiksa dan diputus secara objektif, imparsial, dan berdasarkan hukum.</p>\n      </article>\n      <article>\n        <span>02</span>\n        <h4>Memberikan pelayanan hukum berkeadilan</h4>\n        <p>Menyediakan pelayanan bagi pencari keadilan secara sederhana, cepat, transparan, akuntabel, dan mudah diakses oleh seluruh masyarakat Natuna.</p>\n      </article>\n      <article>\n        <span>03</span>\n        <h4>Meningkatkan kualitas kepemimpinan</h4>\n        <p>Mendorong tata kelola kelembagaan yang efektif melalui kepemimpinan yang responsif, pembinaan aparatur, dan pengawasan berkelanjutan.</p>\n      </article>\n      <article>\n        <span>04</span>\n        <h4>Meningkatkan kredibilitas dan transparansi</h4>\n        <p>Menguatkan kepercayaan publik melalui keterbukaan informasi, integritas aparatur, layanan digital, dan pelaksanaan tugas yang dapat dipertanggungjawabkan.</p>\n      </article>\n    </div>\n  </section>\n\n  <section class=\"visimisi-values-card\">\n    <strong>Nilai pelayanan</strong>\n    <div>\n      <span>Mandiri</span>\n      <span>Berintegritas</span>\n      <span>Profesional</span>\n      <span>Transparan</span>\n      <span>Akuntabel</span>\n    </div>\n  </section>\n</div>','',1,8,'2026-06-18 10:16:51',285,'','2026-06-18 11:09:20',285,NULL,NULL,'2000-01-01 00:00:00',NULL,'{}','{}','{\"show_hits\": \"0\", \"show_tags\": \"0\", \"show_intro\": \"1\", \"show_title\": \"1\", \"link_author\": \"0\", \"link_titles\": \"0\", \"show_author\": \"0\", \"show_noauth\": \"0\", \"link_category\": \"0\", \"show_category\": \"0\", \"show_create_date\": \"0\", \"show_modify_date\": \"0\", \"show_associations\": \"0\", \"show_publish_date\": \"0\", \"info_block_position\": \"0\", \"link_parent_category\": \"0\", \"show_item_navigation\": \"0\", \"show_parent_category\": \"0\", \"info_block_show_title\": \"0\"}',1,10,'','Visi dan misi Pengadilan Negeri Natuna Kelas II.',1,100,'{}',0,'*','pn-natuna-migrasi-2026'),(11,0,'Jenis Layanan pada PTSP Pengadilan Negeri Natuna','jenis-layanan-pada-ptsp-pengadilan-negeri-natuna','<nav class=\"svc-subnav\" aria-label=\"Navigasi Layanan Publik\"><a href=\"/layanan-publik\">Layanan Publik</a><a href=\"/jenis-layanan-ptsp\" aria-current=\"page\">Layanan PTSP</a><a href=\"/standar-pelayanan\">Standar Pelayanan</a><a href=\"/maklumat-pelayanan\">Maklumat</a><a href=\"/kompensasi-layanan\">Kompensasi</a><a href=\"/layanan-disabilitas\">Disabilitas</a><a href=\"/permohonan-informasi\">Permohonan Informasi</a><a href=\"/regulasi-pengaduan\">Pengaduan</a></nav><div class=\"svc-hero\"><div><span class=\"svc-kicker\">Satu Pintu, Satu Meja</span><p class=\"svc-lead\">Pelayanan Terpadu Satu Pintu (PTSP) Pengadilan Negeri Natuna memberikan layanan administrasi peradilan secara terpadu, tertib, dan mudah diakses masyarakat. Seluruh permohonan cukup disampaikan melalui meja PTSP tanpa perlu menemui pejabat atau pegawai lain.</p><ul class=\"svc-facts\"><li><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><circle cx=\"12\" cy=\"12\" r=\"10\"/><polyline points=\"12 6 12 12 16 14\"/></svg>Jam layanan hari ini: <strong class=\"js-service-hours\">08.00&#8211;16.30 WIB</strong></li><li><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M22 11.08V12a10 10 0 1 1-5.93-9.14\"/><polyline points=\"22 4 12 14.01 9 11.01\"/></svg>Bebas biaya perantara</li></ul></div><svg class=\"svc-illus\" viewBox=\"0 0 200 160\" aria-hidden=\"true\"><circle cx=\"100\" cy=\"80\" r=\"72\" fill=\"#fbf2d8\"/><circle cx=\"86\" cy=\"52\" r=\"11\" fill=\"#244b6d\"/><path d=\"M66 92c0-12 9-20 20-20s20 8 20 20\" fill=\"#244b6d\"/><rect x=\"120\" y=\"30\" width=\"46\" height=\"30\" rx=\"9\" fill=\"#b98f24\"/><polygon points=\"130,58 130,70 142,58\" fill=\"#b98f24\"/><polyline points=\"133,45 140,52 153,39\" fill=\"none\" stroke=\"#ffffff\" stroke-width=\"4\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/><rect x=\"112\" y=\"74\" width=\"26\" height=\"16\" rx=\"2\" fill=\"#ffffff\" stroke=\"#d9e0e7\" stroke-width=\"2\"/><rect x=\"48\" y=\"92\" width=\"104\" height=\"30\" rx=\"6\" fill=\"#8f1f0b\"/><rect x=\"44\" y=\"88\" width=\"112\" height=\"8\" rx=\"4\" fill=\"#671607\"/><ellipse cx=\"100\" cy=\"136\" rx=\"60\" ry=\"5\" fill=\"#1f5b4b\" opacity=\"0.18\"/></svg></div><h2>Layanan per Kepaniteraan</h2><div class=\"svc-grid\"><div class=\"svc-card\"><span class=\"svc-icon\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M12 3v18\"/><path d=\"M5 7h14\"/><path d=\"M5 7l-3 6a3.5 3.5 0 0 0 6 0z\"/><path d=\"M19 7l-3 6a3.5 3.5 0 0 0 6 0z\"/><path d=\"M8 21h8\"/></svg></span><h3>Kepaniteraan Perdata</h3><ul><li>Pendaftaran gugatan biasa, gugatan sederhana, perlawanan, verzet, dan permohonan.</li><li>Pendaftaran upaya hukum banding, kasasi, peninjauan kembali, serta penerimaan memori dan kontra memori.</li><li>Permohonan salinan putusan, akta cerai, informasi perkara, dan layanan administrasi perkara perdata lainnya.</li></ul></div><div class=\"svc-card\"><span class=\"svc-icon\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M12 22s8-4 8-10V5l-8-3-8 3v7c0 6 8 10 8 10z\"/></svg></span><h3>Kepaniteraan Pidana</h3><ul><li>Penerimaan pelimpahan berkas perkara pidana.</li><li>Layanan upaya hukum banding, kasasi, dan peninjauan kembali perkara pidana.</li><li>Permohonan izin besuk tahanan, surat keterangan, dan layanan administrasi pidana lainnya sesuai ketentuan.</li></ul></div><div class=\"svc-card\"><span class=\"svc-icon\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M2 3h6a4 4 0 0 1 4 4v14a3 3 0 0 0-3-3H2z\"/><path d=\"M22 3h-6a4 4 0 0 0-4 4v14a3 3 0 0 1 3-3h7z\"/></svg></span><h3>Kepaniteraan Hukum</h3><ul><li>Permohonan informasi publik.</li><li>Surat keterangan tidak pernah dipidana dan layanan surat keterangan lain sesuai ketentuan.</li><li>Layanan legalisasi, riset, dan informasi hukum yang tersedia di pengadilan.</li></ul></div></div><h2>Dokumen Informasi Layanan</h2><div class=\"svc-grid\"><div><button type=\"button\" class=\"svc-zoom\" data-maklumat-zoom=\"/images/layanan/biaya-jenis-layanan.png\" data-maklumat-label=\"Jenis dan Biaya Layanan Pengadilan Negeri Natuna\" aria-label=\"Perbesar dokumen jenis dan biaya layanan\"><img src=\"/images/layanan/biaya-jenis-layanan.png\" alt=\"Jenis dan biaya layanan Pengadilan Negeri Natuna\" loading=\"lazy\" decoding=\"async\"><span class=\"svc-zoom-hint\" aria-hidden=\"true\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\"><circle cx=\"11\" cy=\"11\" r=\"7\"/><path d=\"m21 21-4.3-4.3\"/><path d=\"M11 8v6M8 11h6\"/></svg>Klik untuk perbesar</span></button><span class=\"svc-zoom-caption\">Jenis dan Biaya Layanan</span></div><div><button type=\"button\" class=\"svc-zoom\" data-maklumat-zoom=\"/images/layanan/waktu-layanan.png\" data-maklumat-label=\"Waktu Pelayanan Pengadilan Negeri Natuna\" aria-label=\"Perbesar dokumen waktu pelayanan\"><img src=\"/images/layanan/waktu-layanan.png\" alt=\"Waktu pelayanan Pengadilan Negeri Natuna\" loading=\"lazy\" decoding=\"async\"><span class=\"svc-zoom-hint\" aria-hidden=\"true\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\"><circle cx=\"11\" cy=\"11\" r=\"7\"/><path d=\"m21 21-4.3-4.3\"/><path d=\"M11 8v6M8 11h6\"/></svg>Klik untuk perbesar</span></button><span class=\"svc-zoom-caption\">Waktu Pelayanan</span></div></div><div class=\"svc-note\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><circle cx=\"12\" cy=\"12\" r=\"10\"/><line x1=\"12\" y1=\"16\" x2=\"12\" y2=\"12\"/><line x1=\"12\" y1=\"8\" x2=\"12.01\" y2=\"8\"/></svg><p>Rincian jenis layanan akan terus disesuaikan dengan ketentuan terbaru dan standar pelayanan yang berlaku. Untuk kepastian persyaratan, silakan hubungi petugas PTSP terlebih dahulu.</p></div><div class=\"svc-cta\"><div><h2>Urus perkara tanpa datang ke pengadilan</h2><p>Pendaftaran perkara, pembayaran, dan persidangan tertentu dapat dilakukan secara elektronik melalui e-Court Mahkamah Agung RI.</p></div><div class=\"svc-cta-buttons\"><a class=\"svc-btn svc-btn-gold\" href=\"https://ecourt.mahkamahagung.go.id/\" target=\"_blank\" rel=\"noopener\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M18 13v6a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2V8a2 2 0 0 1 2-2h6\"/><polyline points=\"15 3 21 3 21 9\"/><line x1=\"10\" y1=\"14\" x2=\"21\" y2=\"3\"/></svg>Buka e-Court</a><a class=\"svc-btn svc-btn-line\" href=\"https://wa.me/6281261256661\" target=\"_blank\" rel=\"noopener\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M21 15a2 2 0 0 1-2 2H7l-4 4V5a2 2 0 0 1 2-2h14a2 2 0 0 1 2 2z\"/></svg>Tanya Petugas</a></div></div>','',1,9,'2026-06-18 10:16:51',285,'','2026-06-18 11:09:20',285,NULL,NULL,'2000-01-01 00:00:00',NULL,'{}','{}','{\"show_hits\": \"0\", \"show_tags\": \"0\", \"show_intro\": \"1\", \"show_title\": \"1\", \"link_author\": \"0\", \"link_titles\": \"0\", \"show_author\": \"0\", \"show_noauth\": \"0\", \"link_category\": \"0\", \"show_category\": \"0\", \"show_create_date\": \"0\", \"show_modify_date\": \"0\", \"show_associations\": \"0\", \"show_publish_date\": \"0\", \"info_block_position\": \"0\", \"link_parent_category\": \"0\", \"show_item_navigation\": \"0\", \"show_parent_category\": \"0\", \"info_block_show_title\": \"0\"}',1,20,'','Jenis layanan PTSP Pengadilan Negeri Natuna.',1,83,'{}',0,'*','pn-natuna-migrasi-2026'),(12,0,'Standar Pelayanan','standar-pelayanan','<nav class=\"svc-subnav\" aria-label=\"Navigasi Layanan Publik\"><a href=\"/layanan-publik\">Layanan Publik</a><a href=\"/jenis-layanan-ptsp\">Layanan PTSP</a><a href=\"/standar-pelayanan\" aria-current=\"page\">Standar Pelayanan</a><a href=\"/maklumat-pelayanan\">Maklumat</a><a href=\"/kompensasi-layanan\">Kompensasi</a><a href=\"/layanan-disabilitas\">Disabilitas</a><a href=\"/permohonan-informasi\">Permohonan Informasi</a><a href=\"/regulasi-pengaduan\">Pengaduan</a></nav><div class=\"svc-hero\"><div><span class=\"svc-kicker\">Jaminan Mutu Pelayanan</span><p class=\"svc-lead\">Standar pelayanan peradilan menjadi tolok ukur bagi pengadilan dalam melayani masyarakat dan pencari keadilan. Pengadilan Negeri Natuna berpedoman pada Surat Keputusan Ketua Mahkamah Agung RI Nomor 026/KMA/SK/II/2012 tentang Standar Pelayanan Peradilan.</p></div><svg class=\"svc-illus\" viewBox=\"0 0 200 160\" aria-hidden=\"true\"><circle cx=\"100\" cy=\"80\" r=\"72\" fill=\"#fbf2d8\"/><rect x=\"66\" y=\"30\" width=\"70\" height=\"92\" rx=\"7\" fill=\"#ffffff\" stroke=\"#d9e0e7\" stroke-width=\"2\"/><rect x=\"76\" y=\"44\" width=\"50\" height=\"6\" rx=\"3\" fill=\"#8f1f0b\" opacity=\"0.85\"/><rect x=\"76\" y=\"58\" width=\"42\" height=\"5\" rx=\"2.5\" fill=\"#dfe5eb\"/><rect x=\"76\" y=\"70\" width=\"46\" height=\"5\" rx=\"2.5\" fill=\"#dfe5eb\"/><rect x=\"76\" y=\"82\" width=\"38\" height=\"5\" rx=\"2.5\" fill=\"#dfe5eb\"/><polygon points=\"120,104 126,118 114,118\" fill=\"#b98f24\"/><polygon points=\"130,104 136,118 124,118\" fill=\"#8f1f0b\"/><circle cx=\"125\" cy=\"100\" r=\"13\" fill=\"#b98f24\"/><circle cx=\"125\" cy=\"100\" r=\"7\" fill=\"#fbf2d8\"/><circle cx=\"62\" cy=\"42\" r=\"15\" fill=\"#1f5b4b\"/><polyline points=\"55,42 60,47 70,36\" fill=\"none\" stroke=\"#ffffff\" stroke-width=\"4\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/><ellipse cx=\"100\" cy=\"136\" rx=\"58\" ry=\"5\" fill=\"#1f5b4b\" opacity=\"0.18\"/></svg></div><h2>Ruang Lingkup Standar Pelayanan</h2><div class=\"svc-grid\"><div class=\"svc-card\"><span class=\"svc-icon\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M12 3v18\"/><path d=\"M5 7h14\"/><path d=\"M5 7l-3 6a3.5 3.5 0 0 0 6 0z\"/><path d=\"M19 7l-3 6a3.5 3.5 0 0 0 6 0z\"/><path d=\"M8 21h8\"/></svg></span><h3>Pelayanan Persidangan</h3><p>Kepastian jadwal sidang, tata cara persidangan, dan hak para pihak selama proses berjalan.</p></div><div class=\"svc-card\"><span class=\"svc-icon\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><line x1=\"12\" y1=\"1\" x2=\"12\" y2=\"23\"/><path d=\"M17 5H9.5a3.5 3.5 0 0 0 0 7h5a3.5 3.5 0 0 1 0 7H6\"/></svg></span><h3>Biaya Perkara</h3><p>Transparansi komponen dan besaran panjar biaya perkara serta pengembalian sisa panjar.</p></div><div class=\"svc-card\"><span class=\"svc-icon\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M17 21v-2a4 4 0 0 0-4-4H5a4 4 0 0 0-4 4v2\"/><circle cx=\"9\" cy=\"7\" r=\"4\"/><path d=\"M23 21v-2a4 4 0 0 0-3-3.87\"/><path d=\"M16 3.13a4 4 0 0 1 0 7.75\"/></svg></span><h3>Bantuan Hukum</h3><p>Layanan pembebasan biaya perkara dan Posbakum bagi masyarakat yang tidak mampu.</p></div><div class=\"svc-card\"><span class=\"svc-icon\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><circle cx=\"11\" cy=\"11\" r=\"8\"/><line x1=\"21\" y1=\"21\" x2=\"16.65\" y2=\"16.65\"/></svg></span><h3>Informasi Publik</h3><p>Hak masyarakat memperoleh informasi pengadilan sesuai ketentuan keterbukaan informasi.</p></div><div class=\"svc-card\"><span class=\"svc-icon\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><polygon points=\"11 5 6 9 2 9 2 15 6 15 11 19 11 5\"/><path d=\"M15.54 8.46a5 5 0 0 1 0 7.07\"/><path d=\"M19.07 4.93a10 10 0 0 1 0 14.14\"/></svg></span><h3>Pengaduan</h3><p>Mekanisme penyampaian dan penanganan pengaduan atas pelayanan pengadilan.</p></div><div class=\"svc-card\"><span class=\"svc-icon\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M14 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8z\"/><polyline points=\"14 2 14 8 20 8\"/><line x1=\"16\" y1=\"13\" x2=\"8\" y2=\"13\"/><line x1=\"16\" y1=\"17\" x2=\"8\" y2=\"17\"/></svg></span><h3>Pelayanan Administratif</h3><p>Layanan surat keterangan, salinan putusan, legalisasi, dan administrasi kepaniteraan lainnya.</p></div></div><h2>Dokumen Standar Pelayanan</h2><div class=\"svc-docs\"><a class=\"svc-doc\" href=\"https://drive.google.com/file/d/1z2loaW19M6rHRBe12_LaWA3e27ib5yfJ/view?usp=sharing\" target=\"_blank\" rel=\"noopener\"><span class=\"svc-doc-ic\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M14 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8z\"/><polyline points=\"14 2 14 8 20 8\"/></svg></span><span><strong>SK KMA Nomor 026/KMA/SK/II/2012</strong><span>Standar Pelayanan Peradilan &#8212; dokumen utama</span></span></a><a class=\"svc-doc\" href=\"https://drive.google.com/file/d/1CX9lbNWZdZ4OlZUkEYPdIIl0fKHiR6ZJ/view?usp=sharing\" target=\"_blank\" rel=\"noopener\"><span class=\"svc-doc-ic\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M14 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8z\"/><polyline points=\"14 2 14 8 20 8\"/></svg></span><span><strong>Lampiran SK KMA Nomor 026/KMA/SK/II/2012</strong><span>Rincian standar tiap jenis pelayanan</span></span></a></div><div class=\"svc-note\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><circle cx=\"12\" cy=\"12\" r=\"10\"/><line x1=\"12\" y1=\"16\" x2=\"12\" y2=\"12\"/><line x1=\"12\" y1=\"8\" x2=\"12.01\" y2=\"8\"/></svg><p>Apabila pelayanan yang Anda terima tidak sesuai standar, Anda berhak menyampaikan pengaduan melalui <a href=\"/regulasi-pengaduan\">kanal pengaduan resmi</a> dan memperoleh <a href=\"/kompensasi-layanan\">kompensasi layanan</a>.</p></div>','',1,9,'2026-06-18 10:16:51',285,'','2026-06-18 11:09:20',285,NULL,NULL,'2000-01-01 00:00:00',NULL,'{}','{}','{\"show_hits\": \"0\", \"show_tags\": \"0\", \"show_intro\": \"1\", \"show_title\": \"1\", \"link_author\": \"0\", \"link_titles\": \"0\", \"show_author\": \"0\", \"show_noauth\": \"0\", \"link_category\": \"0\", \"show_category\": \"0\", \"show_create_date\": \"0\", \"show_modify_date\": \"0\", \"show_associations\": \"0\", \"show_publish_date\": \"0\", \"info_block_position\": \"0\", \"link_parent_category\": \"0\", \"show_item_navigation\": \"0\", \"show_parent_category\": \"0\", \"info_block_show_title\": \"0\"}',1,21,'','Standar pelayanan Pengadilan Negeri Natuna.',1,94,'{}',0,'*','pn-natuna-migrasi-2026'),(13,0,'Maklumat Pelayanan','maklumat-pelayanan','<nav class=\"svc-subnav\" aria-label=\"Navigasi Layanan Publik\"><a href=\"/layanan-publik\">Layanan Publik</a><a href=\"/jenis-layanan-ptsp\">Layanan PTSP</a><a href=\"/standar-pelayanan\">Standar Pelayanan</a><a href=\"/maklumat-pelayanan\" aria-current=\"page\">Maklumat</a><a href=\"/kompensasi-layanan\">Kompensasi</a><a href=\"/layanan-disabilitas\">Disabilitas</a><a href=\"/permohonan-informasi\">Permohonan Informasi</a><a href=\"/regulasi-pengaduan\">Pengaduan</a></nav><div class=\"svc-hero\"><div><span class=\"svc-kicker\">Komitmen Pelayanan</span><p class=\"svc-lead\">Maklumat pelayanan merupakan pernyataan kesanggupan Pengadilan Negeri Natuna untuk menyelenggarakan pelayanan sesuai standar pelayanan yang berlaku &#8212; sekaligus kesediaan menerima sanksi apabila janji itu tidak ditepati.</p></div><svg class=\"svc-illus\" viewBox=\"0 0 200 160\" aria-hidden=\"true\"><circle cx=\"100\" cy=\"80\" r=\"72\" fill=\"#fbf2d8\"/><rect x=\"56\" y=\"32\" width=\"88\" height=\"88\" rx=\"7\" fill=\"#ffffff\" stroke=\"#d9e0e7\" stroke-width=\"2\"/><rect x=\"64\" y=\"40\" width=\"72\" height=\"72\" rx=\"4\" fill=\"none\" stroke=\"#e9dfc4\" stroke-width=\"2\"/><rect x=\"76\" y=\"50\" width=\"48\" height=\"7\" rx=\"3.5\" fill=\"#8f1f0b\"/><rect x=\"80\" y=\"64\" width=\"40\" height=\"5\" rx=\"2.5\" fill=\"#dfe5eb\"/><rect x=\"76\" y=\"76\" width=\"48\" height=\"5\" rx=\"2.5\" fill=\"#dfe5eb\"/><circle cx=\"100\" cy=\"102\" r=\"11\" fill=\"#b98f24\"/><circle cx=\"100\" cy=\"102\" r=\"5.5\" fill=\"#fbf2d8\"/><polygon points=\"94,110 90,124 100,117 110,124 106,110\" fill=\"#8f1f0b\"/><ellipse cx=\"100\" cy=\"138\" rx=\"58\" ry=\"5\" fill=\"#1f5b4b\" opacity=\"0.18\"/></svg></div><blockquote><p>&#8220;Sanggup untuk menyelenggarakan pelayanan peradilan dengan standar yang telah ditetapkan, dan apabila kami tidak menepati standar pelayanan tersebut kami siap menerima sanksi sesuai peraturan yang berlaku.&#8221;</p><footer>Lodewyk Ivandrie Simanjuntak, S.H., M.H. &#8212; Ketua Pengadilan Negeri Natuna</footer></blockquote><h2>Dokumen Maklumat</h2><button type=\"button\" class=\"svc-zoom\" data-maklumat-zoom=\"/images/layanan/maklumat-pelayanan-2026.jpg\" data-maklumat-label=\"Maklumat Pelayanan Pengadilan Negeri Natuna\" aria-label=\"Perbesar dokumen maklumat pelayanan\"><img src=\"/images/layanan/maklumat-pelayanan-2026.jpg\" alt=\"Maklumat Pelayanan Pengadilan Negeri Natuna\" loading=\"lazy\" decoding=\"async\"><span class=\"svc-zoom-hint\" aria-hidden=\"true\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\"><circle cx=\"11\" cy=\"11\" r=\"7\"/><path d=\"m21 21-4.3-4.3\"/><path d=\"M11 8v6M8 11h6\"/></svg>Klik untuk perbesar</span></button><div class=\"svc-docs\"><a class=\"svc-doc\" href=\"https://drive.google.com/file/d/1aeePwb1ryGocKMA96D37pn_gHmAweO5G/view?usp=sharing\" target=\"_blank\" rel=\"noopener\"><span class=\"svc-doc-ic\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M14 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8z\"/><polyline points=\"14 2 14 8 20 8\"/></svg></span><span><strong>Dokumen Maklumat Pelayanan</strong><span>Unduh atau lihat versi lengkap</span></span></a></div><div class=\"svc-note\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><circle cx=\"12\" cy=\"12\" r=\"10\"/><line x1=\"12\" y1=\"16\" x2=\"12\" y2=\"12\"/><line x1=\"12\" y1=\"8\" x2=\"12.01\" y2=\"8\"/></svg><p>Untuk layanan informasi publik, tersedia pula <a href=\"/permohonan-informasi\">Maklumat Layanan Informasi Publik</a> yang ditandatangani PPID Pengadilan Negeri Natuna.</p></div>','',1,9,'2026-06-18 10:16:51',285,'','2026-06-18 11:09:20',285,NULL,NULL,'2000-01-01 00:00:00',NULL,'{}','{}','{\"show_hits\": \"0\", \"show_tags\": \"0\", \"show_intro\": \"1\", \"show_title\": \"1\", \"link_author\": \"0\", \"link_titles\": \"0\", \"show_author\": \"0\", \"show_noauth\": \"0\", \"link_category\": \"0\", \"show_category\": \"0\", \"show_create_date\": \"0\", \"show_modify_date\": \"0\", \"show_associations\": \"0\", \"show_publish_date\": \"0\", \"info_block_position\": \"0\", \"link_parent_category\": \"0\", \"show_item_navigation\": \"0\", \"show_parent_category\": \"0\", \"info_block_show_title\": \"0\"}',1,22,'','Maklumat pelayanan Pengadilan Negeri Natuna.',1,72,'{}',0,'*','pn-natuna-migrasi-2026'),(14,0,'Kompensasi Layanan','kompensasi-layanan','<nav class=\"svc-subnav\" aria-label=\"Navigasi Layanan Publik\"><a href=\"/layanan-publik\">Layanan Publik</a><a href=\"/jenis-layanan-ptsp\">Layanan PTSP</a><a href=\"/standar-pelayanan\">Standar Pelayanan</a><a href=\"/maklumat-pelayanan\">Maklumat</a><a href=\"/kompensasi-layanan\" aria-current=\"page\">Kompensasi</a><a href=\"/layanan-disabilitas\">Disabilitas</a><a href=\"/permohonan-informasi\">Permohonan Informasi</a><a href=\"/regulasi-pengaduan\">Pengaduan</a></nav><div class=\"svc-hero\"><div><span class=\"svc-kicker\">Jaminan Layanan</span><p class=\"svc-lead\">Sebagai bentuk tanggung jawab atas mutu pelayanan publik, Pengadilan Negeri Natuna memberikan kompensasi kepada pengguna layanan apabila pelayanan yang diberikan tidak sesuai dengan standar pelayanan yang telah ditetapkan.</p></div><svg class=\"svc-illus\" viewBox=\"0 0 200 160\" aria-hidden=\"true\"><circle cx=\"100\" cy=\"80\" r=\"72\" fill=\"#fbf2d8\"/><path d=\"M100 26l42 15v30c0 28-42 47-42 47s-42-19-42-47V41z\" fill=\"#8f1f0b\"/><path d=\"M100 36l32 11v24c0 21-32 36-32 36s-32-15-32-36V47z\" fill=\"#671607\"/><path d=\"M100 62c4-7 14-7 17 0 3 6-3 12-17 22-14-10-20-16-17-22 3-7 13-7 17 0z\" fill=\"#b98f24\"/><circle cx=\"150\" cy=\"42\" r=\"5\" fill=\"#b98f24\"/><circle cx=\"52\" cy=\"56\" r=\"4\" fill=\"#b98f24\"/><circle cx=\"146\" cy=\"98\" r=\"4\" fill=\"#1f5b4b\" opacity=\"0.5\"/><ellipse cx=\"100\" cy=\"136\" rx=\"58\" ry=\"5\" fill=\"#1f5b4b\" opacity=\"0.18\"/></svg></div><h2>Bentuk Kompensasi</h2><div class=\"svc-grid\"><div class=\"svc-card\"><span class=\"svc-icon\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M21 15a2 2 0 0 1-2 2H7l-4 4V5a2 2 0 0 1 2-2h14a2 2 0 0 1 2 2z\"/></svg></span><h3>Permohonan Maaf</h3><p>Penyampaian permohonan maaf secara langsung atau tertulis kepada pengguna layanan yang dirugikan.</p></div><div class=\"svc-card\"><span class=\"svc-icon\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><polyline points=\"1 4 1 10 7 10\"/><path d=\"M3.51 15a9 9 0 1 0 2.13-9.36L1 10\"/></svg></span><h3>Perbaikan Layanan</h3><p>Perbaikan atau pengulangan layanan sesegera mungkin agar hak pengguna layanan tetap terpenuhi.</p></div><div class=\"svc-card\"><span class=\"svc-icon\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M22 11.08V12a10 10 0 1 1-5.93-9.14\"/><polyline points=\"22 4 12 14.01 9 11.01\"/></svg></span><h3>Prioritas Penanganan</h3><p>Layanan yang tertunda diprioritaskan penyelesaiannya sesuai ketentuan yang berlaku.</p></div></div><h2>Cara Menyampaikan Keluhan</h2><ol class=\"svc-steps\"><li><strong>Sampaikan keluhan Anda</strong><span>Melalui petugas PTSP, meja pengaduan, atau aplikasi SIWAS MA RI dengan menyertakan bukti layanan.</span></li><li><strong>Verifikasi oleh petugas</strong><span>Petugas memeriksa kesesuaian layanan yang diterima dengan standar pelayanan yang berlaku.</span></li><li><strong>Kompensasi diberikan</strong><span>Apabila terbukti tidak sesuai standar, kompensasi diberikan sesuai ketentuan yang berlaku.</span></li></ol><h2>Dokumen Kompensasi Layanan</h2><button type=\"button\" class=\"svc-zoom\" data-maklumat-zoom=\"/images/layanan/kompensasi.png\" data-maklumat-label=\"Kompensasi Layanan Pengadilan Negeri Natuna\" aria-label=\"Perbesar dokumen kompensasi layanan\"><img src=\"/images/layanan/kompensasi.png\" alt=\"Kompensasi layanan Pengadilan Negeri Natuna\" loading=\"lazy\" decoding=\"async\"><span class=\"svc-zoom-hint\" aria-hidden=\"true\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\"><circle cx=\"11\" cy=\"11\" r=\"7\"/><path d=\"m21 21-4.3-4.3\"/><path d=\"M11 8v6M8 11h6\"/></svg>Klik untuk perbesar</span></button><div class=\"svc-cta\"><div><h2>Layanan kami belum sesuai harapan?</h2><p>Sampaikan pengaduan Anda &#8212; setiap masukan membantu kami memperbaiki mutu pelayanan.</p></div><div class=\"svc-cta-buttons\"><a class=\"svc-btn svc-btn-gold\" href=\"/regulasi-pengaduan\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><polygon points=\"11 5 6 9 2 9 2 15 6 15 11 19 11 5\"/><path d=\"M15.54 8.46a5 5 0 0 1 0 7.07\"/></svg>Kanal Pengaduan</a><a class=\"svc-btn svc-btn-line\" href=\"https://wa.me/6281261256661\" target=\"_blank\" rel=\"noopener\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M21 15a2 2 0 0 1-2 2H7l-4 4V5a2 2 0 0 1 2-2h14a2 2 0 0 1 2 2z\"/></svg>WhatsApp Kami</a></div></div>','',1,9,'2026-06-18 10:16:51',285,'','2026-06-18 11:09:20',285,NULL,NULL,'2000-01-01 00:00:00',NULL,'{}','{}','{\"show_hits\": \"0\", \"show_tags\": \"0\", \"show_intro\": \"1\", \"show_title\": \"1\", \"link_author\": \"0\", \"link_titles\": \"0\", \"show_author\": \"0\", \"show_noauth\": \"0\", \"link_category\": \"0\", \"show_category\": \"0\", \"show_create_date\": \"0\", \"show_modify_date\": \"0\", \"show_associations\": \"0\", \"show_publish_date\": \"0\", \"info_block_position\": \"0\", \"link_parent_category\": \"0\", \"show_item_navigation\": \"0\", \"show_parent_category\": \"0\", \"info_block_show_title\": \"0\"}',1,23,'','Kompensasi layanan Pengadilan Negeri Natuna.',1,68,'{}',0,'*','pn-natuna-migrasi-2026'),(15,0,'Layanan Disabilitas','layanan-disabilitas','<nav class=\"svc-subnav\" aria-label=\"Navigasi Layanan Publik\"><a href=\"/layanan-publik\">Layanan Publik</a><a href=\"/jenis-layanan-ptsp\">Layanan PTSP</a><a href=\"/standar-pelayanan\">Standar Pelayanan</a><a href=\"/maklumat-pelayanan\">Maklumat</a><a href=\"/kompensasi-layanan\">Kompensasi</a><a href=\"/layanan-disabilitas\" aria-current=\"page\">Disabilitas</a><a href=\"/permohonan-informasi\">Permohonan Informasi</a><a href=\"/regulasi-pengaduan\">Pengaduan</a></nav><div class=\"svc-hero\"><div><span class=\"svc-kicker\">Peradilan Inklusif</span><p class=\"svc-lead\">Pengadilan Negeri Natuna berkomitmen memberikan layanan yang setara, mudah diakses, dan tidak diskriminatif bagi penyandang disabilitas, lansia, ibu hamil, serta kelompok rentan lainnya.</p></div><svg class=\"svc-illus\" viewBox=\"0 0 200 160\" aria-hidden=\"true\"><circle cx=\"100\" cy=\"80\" r=\"72\" fill=\"#fbf2d8\"/><polygon points=\"58,122 148,122 148,92\" fill=\"#1f5b4b\" opacity=\"0.22\"/><circle cx=\"92\" cy=\"100\" r=\"22\" fill=\"none\" stroke=\"#8f1f0b\" stroke-width=\"7\"/><circle cx=\"124\" cy=\"116\" r=\"7\" fill=\"#8f1f0b\"/><circle cx=\"96\" cy=\"40\" r=\"10\" fill=\"#244b6d\"/><path d=\"M96 52v24h26l10 20\" fill=\"none\" stroke=\"#244b6d\" stroke-width=\"8\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/><path d=\"M96 62h20\" stroke=\"#244b6d\" stroke-width=\"7\" stroke-linecap=\"round\"/><circle cx=\"146\" cy=\"46\" r=\"9\" fill=\"#b98f24\"/><ellipse cx=\"100\" cy=\"140\" rx=\"60\" ry=\"5\" fill=\"#1f5b4b\" opacity=\"0.18\"/></svg></div><h2>Prinsip Layanan</h2><div class=\"svc-grid\"><div class=\"svc-card\"><span class=\"svc-icon\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M12 3v18\"/><path d=\"M5 7h14\"/><path d=\"M5 7l-3 6a3.5 3.5 0 0 0 6 0z\"/><path d=\"M19 7l-3 6a3.5 3.5 0 0 0 6 0z\"/><path d=\"M8 21h8\"/></svg></span><h3>Perlakuan Setara</h3><p>Setiap pengguna layanan dilayani tanpa diskriminasi dalam bentuk apa pun.</p></div><div class=\"svc-card\"><span class=\"svc-icon\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><circle cx=\"13\" cy=\"4\" r=\"2\"/><path d=\"M13 7v5h5l2 5\"/><path d=\"M13 9h4\"/><circle cx=\"11\" cy=\"17\" r=\"4\"/></svg></span><h3>Aksesibilitas</h3><p>Akses fisik gedung dan akses informasi disiapkan agar mudah dijangkau semua orang.</p></div><div class=\"svc-card\"><span class=\"svc-icon\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M21 15a2 2 0 0 1-2 2H7l-4 4V5a2 2 0 0 1 2-2h14a2 2 0 0 1 2 2z\"/></svg></span><h3>Komunikasi Mudah</h3><p>Informasi disampaikan dengan cara yang mudah dipahami sesuai kebutuhan pengguna layanan.</p></div><div class=\"svc-card\"><span class=\"svc-icon\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M17 21v-2a4 4 0 0 0-4-4H5a4 4 0 0 0-4 4v2\"/><circle cx=\"9\" cy=\"7\" r=\"4\"/><path d=\"M23 21v-2a4 4 0 0 0-3-3.87\"/><path d=\"M16 3.13a4 4 0 0 1 0 7.75\"/></svg></span><h3>Prioritas Pendampingan</h3><p>Petugas siap mendampingi pengguna layanan yang membutuhkan bantuan sejak tiba di pengadilan.</p></div></div><h2>Sarana dan Prasarana</h2><div class=\"svc-grid\"><div class=\"svc-card\"><h3>Ramp dan Akses Masuk</h3><p>Jalur landai yang memudahkan pengguna kursi roda memasuki gedung pengadilan.</p></div><div class=\"svc-card\"><h3>Kursi Roda dan Alat Bantu</h3><p>Tersedia sesuai ketersediaan satuan kerja dan dapat diminta melalui petugas.</p></div><div class=\"svc-card\"><h3>Ruang Tunggu Prioritas</h3><p>Ruang tunggu dan jalur layanan yang lebih mudah diakses kelompok rentan.</p></div><div class=\"svc-card\"><h3>Bantuan Petugas PTSP</h3><p>Seluruh informasi layanan dapat dibantu dan dijelaskan langsung oleh petugas.</p></div></div><h2>Fasilitas Akses</h2><button type=\"button\" class=\"svc-zoom\" data-maklumat-zoom=\"/images/layanan/akses-disabilitas.jpg\" data-maklumat-label=\"Fasilitas akses disabilitas Pengadilan Negeri Natuna\" aria-label=\"Perbesar foto fasilitas akses disabilitas\"><img src=\"/images/layanan/akses-disabilitas.jpg\" alt=\"Fasilitas akses disabilitas Pengadilan Negeri Natuna\" loading=\"lazy\" decoding=\"async\"><span class=\"svc-zoom-hint\" aria-hidden=\"true\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\"><circle cx=\"11\" cy=\"11\" r=\"7\"/><path d=\"m21 21-4.3-4.3\"/><path d=\"M11 8v6M8 11h6\"/></svg>Klik untuk perbesar</span></button><div class=\"svc-cta\"><div><h2>Butuh pendampingan saat berkunjung?</h2><p>Beri tahu kami sebelum kedatangan Anda agar petugas dapat menyiapkan bantuan yang diperlukan.</p></div><div class=\"svc-cta-buttons\"><a class=\"svc-btn svc-btn-gold\" href=\"https://wa.me/6281261256661\" target=\"_blank\" rel=\"noopener\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M21 15a2 2 0 0 1-2 2H7l-4 4V5a2 2 0 0 1 2-2h14a2 2 0 0 1 2 2z\"/></svg>Hubungi via WhatsApp</a><a class=\"svc-btn svc-btn-line\" href=\"tel:07733211203\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M22 16.92v3a2 2 0 0 1-2.18 2 19.79 19.79 0 0 1-8.63-3.07 19.5 19.5 0 0 1-6-6 19.79 19.79 0 0 1-3.07-8.67A2 2 0 0 1 4.11 2h3a2 2 0 0 1 2 1.72 12.84 12.84 0 0 0 .7 2.81 2 2 0 0 1-.45 2.11L8.09 9.91a16 16 0 0 0 6 6l1.27-1.27a2 2 0 0 1 2.11-.45 12.84 12.84 0 0 0 2.81.7A2 2 0 0 1 22 16.92z\"/></svg>0773-3211203</a></div></div>','',1,9,'2026-06-18 10:16:51',285,'','2026-06-18 11:09:20',285,NULL,NULL,'2000-01-01 00:00:00',NULL,'{}','{}','{\"show_hits\": \"0\", \"show_tags\": \"0\", \"show_intro\": \"1\", \"show_title\": \"1\", \"link_author\": \"0\", \"link_titles\": \"0\", \"show_author\": \"0\", \"show_noauth\": \"0\", \"link_category\": \"0\", \"show_category\": \"0\", \"show_create_date\": \"0\", \"show_modify_date\": \"0\", \"show_associations\": \"0\", \"show_publish_date\": \"0\", \"info_block_position\": \"0\", \"link_parent_category\": \"0\", \"show_item_navigation\": \"0\", \"show_parent_category\": \"0\", \"info_block_show_title\": \"0\"}',1,24,'','Layanan bagi penyandang disabilitas di Pengadilan Negeri Natuna.',1,67,'{}',0,'*','pn-natuna-migrasi-2026'),(16,0,'Pos Bantuan Hukum','pos-bantuan-hukum','<p>Pengadilan Negeri Natuna menyediakan Pos Bantuan Hukum (Posbakum) bagi masyarakat pencari keadilan sesuai ketentuan yang berlaku.</p><p><img src=\"images/layanan/posbakum.jpg\" alt=\"Pos Bantuan Hukum Pengadilan Negeri Natuna\" loading=\"lazy\"></p><h2>Layanan Posbakum</h2><ul><li>Pemberian informasi, konsultasi, dan advis hukum.</li><li>Bantuan pembuatan dokumen hukum yang dibutuhkan.</li><li>Informasi mengenai organisasi bantuan hukum atau advokat yang dapat memberikan bantuan hukum.</li></ul><p>Informasi lebih lanjut dapat diperoleh melalui meja informasi atau petugas PTSP Pengadilan Negeri Natuna.</p>','',1,10,'2026-06-18 10:16:51',285,'','2026-06-18 11:09:20',285,NULL,NULL,'2000-01-01 00:00:00',NULL,'{}','{}','{\"show_hits\": \"0\", \"show_tags\": \"0\", \"show_intro\": \"1\", \"show_title\": \"1\", \"link_author\": \"0\", \"link_titles\": \"0\", \"show_author\": \"0\", \"show_noauth\": \"0\", \"link_category\": \"0\", \"show_category\": \"0\", \"show_create_date\": \"0\", \"show_modify_date\": \"0\", \"show_associations\": \"0\", \"show_publish_date\": \"0\", \"info_block_position\": \"0\", \"link_parent_category\": \"0\", \"show_item_navigation\": \"0\", \"show_parent_category\": \"0\", \"info_block_show_title\": \"0\"}',1,30,'','Pos Bantuan Hukum Pengadilan Negeri Natuna.',1,74,'{}',0,'*','pn-natuna-migrasi-2026'),(17,0,'Prosedur Pembebasan Biaya Perkara (Prodeo)','prosedur-pembebasan-biaya-perkara-prodeo','<p>Pembebasan biaya perkara dapat diberikan kepada masyarakat yang tidak mampu secara ekonomi sesuai ketentuan yang berlaku.</p><h2>Persyaratan Umum</h2><ol><li>Mengisi formulir permohonan bantuan hukum atau pembebasan biaya perkara.</li><li>Menyerahkan fotokopi Kartu Keluarga dan KTP.</li><li>Melampirkan Surat Keterangan Tidak Mampu (SKTM) dari kepala desa/lurah/kepala wilayah setempat atau dokumen keterangan lain yang sah.</li><li>Menyerahkan berkas atau bukti yang berkaitan dengan permohonan bantuan hukum.</li></ol><p>Petugas PTSP akan membantu memberikan informasi awal mengenai kelengkapan persyaratan sesuai ketentuan terbaru.</p>','',1,10,'2026-06-18 10:16:51',285,'','2026-06-18 11:09:20',285,NULL,NULL,'2000-01-01 00:00:00',NULL,'{}','{}','{\"show_hits\": \"0\", \"show_tags\": \"0\", \"show_intro\": \"1\", \"show_title\": \"1\", \"link_author\": \"0\", \"link_titles\": \"0\", \"show_author\": \"0\", \"show_noauth\": \"0\", \"link_category\": \"0\", \"show_category\": \"0\", \"show_create_date\": \"0\", \"show_modify_date\": \"0\", \"show_associations\": \"0\", \"show_publish_date\": \"0\", \"info_block_position\": \"0\", \"link_parent_category\": \"0\", \"show_item_navigation\": \"0\", \"show_parent_category\": \"0\", \"info_block_show_title\": \"0\"}',1,31,'','Prosedur pembebasan biaya perkara atau prodeo.',1,67,'{}',0,'*','pn-natuna-migrasi-2026'),(18,0,'Biaya Perkara','biaya-perkara','<p>Informasi biaya panjar perkara Pengadilan Negeri Natuna disediakan untuk memberi kepastian informasi kepada masyarakat pencari keadilan.</p><ul><li><a href=\"https://drive.google.com/file/d/1jZHj-d9NMmoPFSlCIi-pYkWvAulXd4Vf/view?usp=sharing\" target=\"_blank\" rel=\"noopener\">Biaya Panjar Perkara Tahun 2020</a></li><li><a href=\"https://drive.google.com/file/d/1PiwfGbr_5iIGmTBn4UM9Ku4VnfbBqvHM/view?usp=sharing\" target=\"_blank\" rel=\"noopener\">Biaya Panjar Perkara Tahun 2021</a></li><li><a href=\"https://drive.google.com/file/d/1jkfUUkYhTiXaz2p_AUijeNENcL-5S_Uk/view?usp=sharing\" target=\"_blank\" rel=\"noopener\">Biaya Panjar Perkara Tahun 2022</a></li><li><a href=\"https://drive.google.com/file/d/1WeLyTaVpQu-U4otQwrdYB8hcwdm2j_aK/view?usp=sharing\" target=\"_blank\" rel=\"noopener\">Biaya Panjar Perkara Tahun 2023</a></li><li><a href=\"https://drive.google.com/file/d/1PjMa9neg5IywkWtXtffC_IM9YiGCnmCk/view?usp=sharing\" target=\"_blank\" rel=\"noopener\">Biaya Panjar Perkara Tahun 2025</a></li><li><a href=\"https://drive.google.com/file/d/1hdBK0Oi4AHpp3Ol309_GWSa0W3jDByQO/view?usp=sharing\" target=\"_blank\" rel=\"noopener\">Biaya Panjar Perkara Tahun 2026</a></li><li><a href=\"https://drive.google.com/file/d/1qeRf3QpFGqboWcV56tcQsWef-Hq98OwV/view?usp=sharing\" target=\"_blank\" rel=\"noopener\">PP Nomor 5 Tahun 2019 tentang PNBP pada Mahkamah Agung dan Badan Peradilan</a></li></ul><p>Informasi biaya perkara harus diverifikasi kembali sebelum dipublikasikan ke website produksi.</p>','',1,11,'2026-06-18 10:16:51',285,'','2026-06-18 16:03:48',285,NULL,NULL,'2000-01-01 00:00:00',NULL,'{}','{}','{\"show_hits\": \"0\", \"show_tags\": \"0\", \"show_intro\": \"1\", \"show_title\": \"1\", \"link_author\": \"0\", \"link_titles\": \"0\", \"show_author\": \"0\", \"show_noauth\": \"0\", \"link_category\": \"0\", \"show_category\": \"0\", \"show_create_date\": \"0\", \"show_modify_date\": \"0\", \"show_associations\": \"0\", \"show_publish_date\": \"0\", \"info_block_position\": \"0\", \"link_parent_category\": \"0\", \"show_item_navigation\": \"0\", \"show_parent_category\": \"0\", \"info_block_show_title\": \"0\"}',1,87,'','Informasi biaya perkara Pengadilan Negeri Natuna.',1,90,'{}',0,'*','pn-natuna-case-legal-migrasi-2026'),(19,0,'Prosedur Permohonan Informasi','prosedur-permohonan-informasi','<nav class=\"svc-subnav\" aria-label=\"Navigasi Layanan Publik\"><a href=\"/layanan-publik\">Layanan Publik</a><a href=\"/jenis-layanan-ptsp\">Layanan PTSP</a><a href=\"/standar-pelayanan\">Standar Pelayanan</a><a href=\"/maklumat-pelayanan\">Maklumat</a><a href=\"/kompensasi-layanan\">Kompensasi</a><a href=\"/layanan-disabilitas\">Disabilitas</a><a href=\"/permohonan-informasi\" aria-current=\"page\">Permohonan Informasi</a><a href=\"/regulasi-pengaduan\">Pengaduan</a></nav><div class=\"svc-hero\"><div><span class=\"svc-kicker\">Keterbukaan Informasi Publik</span><p class=\"svc-lead\">Permohonan informasi di Pengadilan Negeri Natuna dilayani melalui prosedur biasa dan prosedur khusus sesuai Keputusan Ketua Mahkamah Agung RI Nomor 2-144/KMA/SK/VIII/2022 tentang Standar Pelayanan Informasi Publik di Pengadilan.</p><ul class=\"svc-facts\"><li><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><circle cx=\"12\" cy=\"12\" r=\"10\"/><polyline points=\"12 6 12 12 16 14\"/></svg>Jam layanan hari ini: <strong class=\"js-service-hours\">08.00&#8211;16.30 WIB</strong></li><li><a href=\"mailto:pn.natuna@gmail.com\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M4 4h16c1.1 0 2 .9 2 2v12c0 1.1-.9 2-2 2H4c-1.1 0-2-.9-2-2V6c0-1.1.9-2 2-2z\"/><polyline points=\"22,6 12,13 2,6\"/></svg>pn.natuna@gmail.com</a></li></ul></div><svg class=\"svc-illus\" viewBox=\"0 0 200 160\" aria-hidden=\"true\"><circle cx=\"100\" cy=\"80\" r=\"72\" fill=\"#fbf2d8\"/><rect x=\"56\" y=\"36\" width=\"60\" height=\"80\" rx=\"6\" fill=\"#ffffff\" stroke=\"#d9e0e7\" stroke-width=\"2\"/><rect x=\"65\" y=\"48\" width=\"40\" height=\"5\" rx=\"2.5\" fill=\"#dfe5eb\"/><rect x=\"65\" y=\"60\" width=\"34\" height=\"5\" rx=\"2.5\" fill=\"#dfe5eb\"/><rect x=\"65\" y=\"72\" width=\"38\" height=\"5\" rx=\"2.5\" fill=\"#dfe5eb\"/><circle cx=\"118\" cy=\"88\" r=\"21\" fill=\"rgba(251,242,216,0.55)\" stroke=\"#b98f24\" stroke-width=\"7\"/><line x1=\"133\" y1=\"103\" x2=\"148\" y2=\"118\" stroke=\"#b98f24\" stroke-width=\"8\" stroke-linecap=\"round\"/><circle cx=\"146\" cy=\"42\" r=\"14\" fill=\"#244b6d\"/><rect x=\"144\" y=\"40\" width=\"4\" height=\"10\" rx=\"2\" fill=\"#ffffff\"/><circle cx=\"146\" cy=\"34.5\" r=\"2.4\" fill=\"#ffffff\"/><ellipse cx=\"100\" cy=\"136\" rx=\"58\" ry=\"5\" fill=\"#1f5b4b\" opacity=\"0.18\"/></svg></div><h2>Dua Jalur Prosedur</h2><div class=\"svc-grid\"><div class=\"svc-card\"><span class=\"svc-icon\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M14 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8z\"/><polyline points=\"14 2 14 8 20 8\"/><line x1=\"16\" y1=\"13\" x2=\"8\" y2=\"13\"/><line x1=\"16\" y1=\"17\" x2=\"8\" y2=\"17\"/></svg></span><h3>Prosedur Biasa</h3><p>Digunakan apabila permohonan disampaikan tidak langsung, informasi bervolume besar, informasi belum tersedia, atau memerlukan penelaahan PPID terlebih dahulu.</p></div><div class=\"svc-card\"><span class=\"svc-icon\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><polygon points=\"13 2 3 14 12 14 11 22 21 10 12 10 13 2\"/></svg></span><h3>Prosedur Khusus</h3><p>Digunakan untuk permohonan langsung terhadap informasi yang wajib diumumkan, tersedia setiap saat, atau dapat diberikan segera sesuai ketentuan.</p></div></div><h2>Alur Permohonan</h2><ol class=\"svc-steps\"><li><strong>Ajukan permohonan</strong><span>Datang langsung ke petugas informasi atau meja PTSP, atau sampaikan secara tertulis melalui surat maupun email resmi pengadilan.</span></li><li><strong>Registrasi dan tanda terima</strong><span>Permohonan dicatat dalam register dan pemohon menerima tanda bukti permohonan informasi.</span></li><li><strong>Pemenuhan informasi</strong><span>Petugas atau PPID menelaah dan menyampaikan informasi, atau memberitahukan alasannya apabila informasi dikecualikan.</span></li><li><strong>Keberatan</strong><span>Apabila tidak puas atas layanan informasi, pemohon dapat mengajukan keberatan kepada atasan PPID sesuai ketentuan.</span></li></ol><h2>Maklumat Layanan Informasi Publik</h2><blockquote><p>&#8220;Siap memberikan pelayanan informasi publik secara cepat, tepat waktu, biaya ringan, dan sederhana sesuai dengan ketentuan peraturan perundang-undangan.&#8221;</p><footer>Jhivo Wilanda, S.H. &#8212; PPID Pengadilan Negeri Natuna</footer></blockquote><button type=\"button\" class=\"svc-zoom\" data-maklumat-zoom=\"/images/layanan/maklumat-layanan-informasi-publik.png\" data-maklumat-label=\"Maklumat Layanan Informasi Publik Pengadilan Negeri Natuna\" aria-label=\"Perbesar dokumen maklumat layanan informasi publik\"><img src=\"/images/layanan/maklumat-layanan-informasi-publik.png\" alt=\"Maklumat Layanan Informasi Publik Pengadilan Negeri Natuna\" loading=\"lazy\" decoding=\"async\"><span class=\"svc-zoom-hint\" aria-hidden=\"true\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\"><circle cx=\"11\" cy=\"11\" r=\"7\"/><path d=\"m21 21-4.3-4.3\"/><path d=\"M11 8v6M8 11h6\"/></svg>Klik untuk perbesar</span></button><div class=\"svc-cta\"><div><h2>Ingin mengajukan permohonan informasi?</h2><p>Petugas informasi kami siap membantu menjelaskan jenis informasi yang tersedia dan persyaratannya.</p></div><div class=\"svc-cta-buttons\"><a class=\"svc-btn svc-btn-gold\" href=\"mailto:pn.natuna@gmail.com\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M4 4h16c1.1 0 2 .9 2 2v12c0 1.1-.9 2-2 2H4c-1.1 0-2-.9-2-2V6c0-1.1.9-2 2-2z\"/><polyline points=\"22,6 12,13 2,6\"/></svg>Kirim Email</a><a class=\"svc-btn svc-btn-line\" href=\"https://wa.me/6281261256661\" target=\"_blank\" rel=\"noopener\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M21 15a2 2 0 0 1-2 2H7l-4 4V5a2 2 0 0 1 2-2h14a2 2 0 0 1 2 2z\"/></svg>WhatsApp</a></div></div>','',1,9,'2026-06-18 10:16:51',285,'','2026-06-18 11:09:20',285,NULL,NULL,'2000-01-01 00:00:00',NULL,'{}','{}','{\"show_hits\": \"0\", \"show_tags\": \"